static class LeoActions
{
    public static readonly string[] Names=["files_with_app","notes_open","note_add","path_reveal","media_file","local_app_open","path_open","module_list","module_run","command_text","media_open","media_status","media_toggle","media_play","media_pause","media_next","media_previous","media_stop","chat_open","app_search","app_open","app_open_name","todo_natural","todo_complete_title","web_open","todo_skip_repeat","todo_undo","music_client","music_pause","music_lyrics","music_status","combo_name","scene_watch","launcher_open","clipboard_open","clipboard_pin_text","football_open","football_facts","todos_open","todo_list","todo_add","todo_complete","todo_remind","todo_repeat","todo_edit","todo_move","todo_snooze","music_open","music_search","music_play","music_step","todo_postpone","todo_stop_repeat","match_add","web_search","watch_open","proxy_status","proxy_on","proxy_off","terminal_open","pet_size","fullscreen_hide","favorite_app","alias_app","files_open"];
    public static readonly HashSet<string> ReadOnly=["module_list","football_facts","todo_list","proxy_status","music_search","music_status","media_status","app_search"];
    public const string Description="notes_open打开便签，value可作为待保存草稿；note_add仅在用户明确要求记下内容时保存文字便签；path_reveal打开文件所在位置；media_file用PotPlayer打开明确提供的媒体文件。path_open为用户明确提供的本机绝对文件/文件夹路径；local_app_open为module_list返回的自定义应用ID，不得猜测。media_open/media_status与media_toggle/media_play/media_pause/media_next/media_previous/media_stop用空字符串控制已选择或正在播放的播放器，可用media_status返回的精确Id指定value；module_list查询扩展动作，module_run的value为返回的ext:模块id:命令id，或JSON{id,value}传入扩展参数；command_text为明确的本地口令；todo_natural由本地解析使用，模型安排事项请用todo_add/todo_repeat。按action填写value：todo_undo用空字符串撤销最近一次清单修改；todo_skip_repeat用精确事项id仅跳过这次重复；界面打开/代理/终端/files_open用空字符串；web_search为关键词；watch_open为1到4；pet_size为80到230整数；fullscreen_hide为on/off；clipboard_pin_text为用户明确要求保存的文字。football_facts为球队名或今晚比赛。todo_list为YYYY-MM-DD或week:YYYY-MM-DD；todo_add为JSON字符串{title,day(YYYY-MM-DD),reminder(可省略，带时区的ISO时间)}；todo_complete为从todo_list获得的精确id；todo_remind为JSON{id,time(带时区ISO时间或空字符串取消)}；favorite_app为JSON{app_id,enabled(bool)}，alias_app为JSON{app_id,alias}，app_id必须来自search_apps。todos_open的value可为week。不要猜测待办id或应用id。todo_repeat为JSON{title,day,frequency(daily或weekly),reminder(可省略)}；todo_postpone为精确事项id，或day:YYYY-MM-DD批量顺延该日未完成；todo_stop_repeat为JSON{series_id,after(YYYY-MM-DD)}停止该日期之后的重复；match_add为football_facts返回的ESPN比赛Id，自动加入清单并提前10分钟提醒，勿猜id。todo_edit为JSON{id,title}只修改本次标题；todo_move为JSON{id,day(YYYY-MM-DD)}改期并移动提醒；todo_snooze为JSON{id,minutes(10或60)}稍后提醒。music_open为空字符串或搜索词；music_search为歌名/歌手，返回候选Id；music_play为music_search提供的精确Id，只有用户要求播放时使用。不要猜歌曲编号，存在歧义先给出候选供选择。music_step为1或-1，手动切换当前Leo点歌列表的下一首或上一首；音乐工具只能报告歌曲已发送客户端，不能假称实际已播放。提醒只在Leo运行时触发。只在用户明确要求时改变代理、收藏、剪贴板或其它设置。";
}
sealed partial class PetForm
{
    readonly System.Windows.Forms.Timer reminderTimer=new(){Interval=15000};
    readonly TodoStore todoStore;
    readonly HashSet<string> presentedReminders=new();
    static string ReminderKey(DailyTask t)=>t.Id+":"+t.Reminder?.ToString("O")+":"+t.SnoozedUntil?.ToString("O");
    void CheckReminders()
    {
        bool concentrating=focus.Active(DateTimeOffset.Now);
        if(concentrating&&reminders!=null&&!reminders.IsDisposed)reminders.Retain(t=>focus.AllowImportant&&(t.Important||t.MatchId!=null));
        if(hiddenForFullscreen||todoClient.Quiet().Contains(DateTime.Now)){if(reminders?.Visible==true)reminders.Hide();return;}
        if(reminders!=null&&!reminders.IsDisposed&&!reminders.Visible&&reminders.PendingCount>0)reminders.Present([]);
        try{todoClient.EnsureThrough(DateOnly.FromDateTime(DateTime.Today).AddDays(35));var due=todoClient.Due(DateTimeOffset.Now).Where(t=>!matchSyncBusy||t.MatchId==null).ToArray();if(due.Length==0)return;
            foreach(var task in due){string key="reminder:"+ReminderKey(task);if(!notices.Items.Any(i=>i.UniqueKey==key)||notices.Error!=null)notices.Add(task.Title,"reminder",task.Id,key);}
            presentedReminders.IntersectWith(due.Select(ReminderKey));var visible=due.Where(t=>focus.ShouldInterrupt(t,DateTimeOffset.Now)&&!presentedReminders.Contains(ReminderKey(t))).ToArray();
            if(visible.Length>0){if(reminders==null||reminders.IsDisposed)reminders=new ReminderForm(todoStore,OpenReminderTask);reminders.Present(visible);tray.BalloonTipTitle="Leo · 清单提醒";tray.BalloonTipText=string.Join("\n",visible.Take(3).Select(t=>t.Title))+"\n可在通知收纳盒再次查看";tray.ShowBalloonTip(10000);foreach(var task in visible)presentedReminders.Add(ReminderKey(task));}
            var delivered=notices.Error==null?due:visible;if(delivered.Length>0)todoClient.From("reminder-scheduler").Acknowledge(delivered);
        }catch{/* Failed reminder saves remain eligible for the next check. */}
    }
    Task<string> ExecuteLeoAction(string action,string value,CancellationToken token)=>commands.ExecuteAsync(new(action,value,"chat"),token);
    async Task<string> ExecuteLeoActionCore(string action,string value,CancellationToken token){token.ThrowIfCancellationRequested();if(!LeoActions.Names.Contains(action))throw new ArgumentException("不支持的功能");Modules.Require(prefs,Modules.ForAction(action));
        switch(action){
            case "files_with_app":{using var doc=JsonDocument.Parse(value);var root=doc.RootElement;string app=root.TryGetProperty("application",out var application)?application.GetString()??"":"";var paths=root.GetProperty("paths").EnumerateArray().Select(e=>e.GetString()??"").ToArray();var start=root.TryGetProperty("module",out var module)&&module.GetString() is {Length:>0} moduleId?FileDropActions.ConfiguredStart(prefs,moduleId,paths):FileDropActions.AppStart(app,paths);if(!previewMode)Process.Start(start);return "已交给所选应用。";}
            case "notes_open":case "note_add":throw new InvalidOperationException("便签动作必须通过已注册模块执行");
            case "path_reveal":{string path=LocalPath.Resolve(value);if(!previewMode)Process.Start(FileDropActions.FolderStart(path));return "已打开所在文件夹。";}
            case "path_open":{string path=LocalPath.Resolve(value);if(!previewMode)Process.Start(new ProcessStartInfo(path){UseShellExecute=true});return "已打开 "+Path.GetFileName(path.TrimEnd(Path.DirectorySeparatorChar));}
            case "local_app_open":return await commands.ExecuteAsync(new("local:"+value,"",commands.CurrentSource),token);
            case "module_list":return JsonSerializer.Serialize(new{modules=commands.Modules.Select(m=>new{m.Id,m.Name,m.Version,m.Enabled,m.Actions}),applications=(prefs.ApplicationModules??[]).Select(a=>new{a.Id,a.Name,a.Enabled,action="local_app_open"}),extensions=commands.Extensions.Load().Select(m=>new{m.Id,m.Name,m.Version,m.Runtime,commands=m.Commands.Select(c=>new{c.Id,c.Title,c.Phrases,action="ext:"+m.Id+":"+c.Id})})});
            case "module_run":{string id=value,arg="";if(value.StartsWith('{')){using var doc=JsonDocument.Parse(value);id=doc.RootElement.GetProperty("id").GetString()??"";arg=doc.RootElement.TryGetProperty("value",out var v)?v.GetString()??"":"";}if(!id.StartsWith("ext:"))throw new ArgumentException("请使用module_list返回的扩展动作ID");return await commands.ExecuteAsync(new(id,arg,"chat-module"),token);}
            case "command_text":return await commands.ExecuteTextAsync(value,commands.CurrentSource,token);
            case "chat_open":ShowChat();return "已打开聊天。";

            case "app_search":return JsonSerializer.Serialize(new{apps=new AppTools(()=>launcher.FileApplications,launcher.LaunchFromAssistant,()=>prefs.Aliases).FindLocal(value).Select(a=>new{app_id=AppTools.Id(a),name=a.Name})});
            case "app_open":{var app=launcher.FileApplications.Where(AppTools.Launchable).SingleOrDefault(a=>AppTools.Id(a)==value)??throw new ArgumentException("应用不在当前索引，请重新搜索");return await launcher.LaunchFromAssistantAsync(app,commands.CurrentSource,token);}
            case "app_open_name":{var found=new AppTools(()=>launcher.FileApplications,launcher.LaunchFromAssistant,()=>prefs.Aliases).FindLocal(value);var exact=found.Where(a=>Catalog.Normalize(a.Name)==Catalog.Normalize(value)).ToArray();if(found.Length!=1&&exact.Length!=1){ShowLauncher();launcher.PreviewTyping(value);return found.Length==0?"未找到应用，请检查名称或等待索引完成。":"找到多个应用，请在搜索框中选择。";}var app=exact.Length==1?exact[0]:found[0];return await launcher.LaunchFromAssistantAsync(app,commands.CurrentSource,token);}
            case "web_open":{FootTools.ValidateUrl(value);string url=value;if(!previewMode)Process.Start(FootTools.EdgeUrlStart(url));return "已打开网址";}
            case "launcher_open":ShowLauncher();if(value=="web")launcher.PreviewTyping("网页搜索 ");return "已打开应用搜索，可以查看收藏、设置简称与排序。";
            case "football_open":launcher.OpenFootballFromAssistant();return "已打开足球日程、球队详情与观赛网址。";
            case "todos_open":case "todo_list":case "todo_add":case "todo_repeat":case "todo_edit":case "todo_move":case "todo_snooze":case "todo_complete":case "todo_remind":case "todo_postpone":case "todo_stop_repeat":case "todo_skip_repeat":case "todo_undo":case "todo_natural":case "todo_complete_title":throw new InvalidOperationException("清单动作必须经过已注册模块");
            case "combo_name":case "scene_watch":throw new InvalidOperationException("组合必须经过已注册执行器");
            case "match_add":throw new InvalidOperationException("比赛安排必须经过已注册桥接能力");
            case "web_search":if(string.IsNullOrWhiteSpace(value))throw new ArgumentException("请输入搜索内容");if(!previewMode)Process.Start(FootTools.EdgeStart(value));return "已用Edge搜索："+value;
            case "watch_open":{if(!int.TryParse(value,out var index)||index<1||index>4)throw new ArgumentException("观赛入口为1到4");var link=new WatchLinkStore(previewMode?null:Path.Combine(Store.Root,"leo-watch-links.json")).Items[index-1];if(link.Url.Length==0)throw new ArgumentException("这个观赛入口还没填写网址，请在足球窗口编辑");if(!previewMode)Process.Start(FootTools.EdgeUrlStart(link.Url));return "已用Edge打开："+link.Name;}

            case "terminal_open":if(!previewMode)Process.Start(FootTools.TerminalStart());return "已请求打开管理员终端；是否授权由Windows确认。";
            case "pet_size":{if(!int.TryParse(value,out int size)||size<80||size>230)throw new ArgumentException("大小范围80至230");prefs.PetSize=size;ResizePet();if(!previewMode)Store.Save(prefs);return "Leo大小已调整为"+size;}
            case "fullscreen_hide":if(value is not("on" or "off"))throw new ArgumentException("请使用on或off");prefs.HideInFullscreen=value=="on";if(!previewMode)Store.Save(prefs);PollFullscreen();return prefs.HideInFullscreen?"已开启全屏自动隐藏":"已关闭全屏自动隐藏";
            case "favorite_app":case "alias_app":{using var doc=JsonDocument.Parse(value);var r=doc.RootElement;string id=r.GetProperty("app_id").GetString()!;var app=launcher.FileApplications.FirstOrDefault(a=>AppTools.Id(a)==id)??throw new ArgumentException("应用ID不存在，请先search_apps");if(action=="favorite_app"){bool enabled=r.GetProperty("enabled").GetBoolean();prefs.Favorites.RemoveAll(t=>t.Equals(app.Target,StringComparison.OrdinalIgnoreCase));if(enabled)prefs.Favorites.Add(app.Target);}else{string alias=r.GetProperty("alias").GetString()?.Trim()??"";if(alias.Length<1||alias.Length>30)throw new ArgumentException("简称应为1至30个字");prefs.Aliases[app.Target]=(prefs.Aliases.GetValueOrDefault(app.Target)??[]).Append(alias).Distinct().ToArray();}if(!previewMode)Store.Save(prefs);return "已更新"+app.Name+(action=="alias_app"?"的简称":"的收藏状态");}
            case "files_open":if(!previewMode){using var picker=new OpenFileDialog{Title="选择要交给Leo的文件",Multiselect=true};if(picker.ShowDialog()!=DialogResult.OK)return "已取消选择文件";AcceptDrop(new DataObject(DataFormats.FileDrop,picker.FileNames));}return "已打开拖放动作面板，可复制路径、记便签、添加待办或选择应用。";
            case "football_facts":{string team=QuickRouter.Team(value);if(team.Length>0){var club=Club.For(team);var data=TeamData.Load(club);bool stale=false;if(!previewMode&&(data.MatchesUpdated<DateTimeOffset.UtcNow.AddMinutes(-10)||data.TableUpdated<DateTimeOffset.UtcNow.AddMinutes(-10))){var result=await TeamData.Fetch(club,data,token);data=result.Data;stale=result.MatchesFailed||result.TableFailed;}if(value.StartsWith("view:"))return JsonSerializer.Serialize(new{data,stale});return JsonSerializer.Serialize(new{source="ESPN",now=DateTimeOffset.Now,team,stale,data.MatchesUpdated,data.TableUpdated,matches=data.Matches.OrderByDescending(m=>m.Kickoff).Take(25),table=data.Rows});}var cache=FootballFeed.LoadCache();bool staleCache=false;if(!previewMode&&cache.Updated<DateTimeOffset.UtcNow.AddMinutes(-10))try{cache=await FootballFeed.FetchAsync(cache,token);}catch(System.Net.Http.HttpRequestException)when(value.StartsWith("view:")){staleCache=true;}if(value.StartsWith("view:"))return JsonSerializer.Serialize(new{cache,stale=staleCache});return JsonSerializer.Serialize(new{source="ESPN",cache.Updated,cache.FailedSources,matches=cache.Matches.Where(m=>FootballFeed.IsRecent(m,DateTimeOffset.UtcNow)&&(FootballFeed.FollowTags(m,FootballForm.FollowingNames).Length>0||FootballFeed.IsFocus(m))).OrderBy(m=>m.Kickoff).Take(30)});}
        }throw new ArgumentException("不支持的功能");
    }
    public async Task<Dictionary<string,bool>> VerifyBrainActions(){var checks=new Dictionary<string,bool>();var token=CancellationToken.None;string day=DateTime.Today.AddDays(2).ToString("yyyy-MM-dd");await ExecuteLeoAction("todo_add",JsonSerializer.Serialize(new{title="工具测试事项",day,reminder=DateTimeOffset.Now.AddDays(2).ToString("O")}),token);var task=todoStore.Items.Single();checks["brain_creates_dated_task_and_reminder"]=task.Day==DateOnly.FromDateTime(DateTime.Today.AddDays(2))&&task.Reminder!=null;await ExecuteLeoAction("todos_open","week",token);checks["brain_and_planner_share_same_store"]=todoWindow?.Count==1&&todoWindow.View.IsWeekly;string listed=await ExecuteLeoAction("todo_list",day,token);checks["brain_reads_actual_task_ids"]=listed.Contains(task.Id);await ExecuteLeoAction("todo_complete",task.Id,token);checks["brain_completes_task_in_planner"]=todoStore.Items.Single().Completed!=null&&todoWindow?.CompletedCount==1;await ExecuteLeoAction("todo_remind",JsonSerializer.Serialize(new{id=task.Id,time=""}),token);checks["brain_cancels_existing_reminder"]=todoStore.Items.Single().Reminder==null;try{await ExecuteLeoAction("todo_remind",JsonSerializer.Serialize(new{id="missing",time=""}),token);checks["brain_rejects_unknown_task_id"]=false;}catch(ArgumentException){checks["brain_rejects_unknown_task_id"]=true;}todoWindow?.Close();return checks;}
}
